<template>
  <div class="page"><button class="back-link" @click="router.push('/tasks')">← Back to tasks</button><header class="page-header"><div><div class="detail-top"><span class="status-badge" :class="task.status?.toLowerCase()">{{pretty(task.status)}}</span><span class="priority-badge" :class="task.priority?.toLowerCase()">{{task.priority}} priority</span></div><h1 class="detail-title">{{task.title}}</h1><p class="page-subtitle">Task details and current progress.</p></div></header><section class="detail-grid"><div class="card detail-card"><h2 class="section-title">About this task</h2><p class="detail-description">{{task.description||'No description was added for this task.'}}</p><div class="info-grid"><div class="info-item"><span>Start date</span><strong>{{formatDate(task.startDate)}}</strong></div><div class="info-item"><span>Due date</span><strong>{{formatDate(task.endDate)}}</strong></div><div class="info-item"><span>Priority</span><strong>{{task.priority}}</strong></div><div class="info-item"><span>Status</span><strong>{{pretty(task.status)}}</strong></div></div><div class="progress-wrap" style="padding:22px 0 0"><div class="progress-head"><span>Task completion</span><b>{{task.progress||0}}%</b></div><div class="progress-track"><div class="progress-fill" :style="{width:(task.progress||0)+'%'}"></div></div></div><div class="action-row"><button v-if="task.status!=='COMPLETED'" class="primary-button" @click="completeTask">Mark complete</button><button class="secondary-button" @click="router.push('/tasks')">Back to list</button></div><p v-if="message" class="success-message">{{message}}</p></div><aside><div class="card side-card"><h2 class="section-title">Assigned to</h2><div class="person"><div class="person-avatar">{{initial(task.employeeName)}}</div><div><strong>{{task.employeeName||'Unassigned'}}</strong><span>Employee</span></div></div></div><div class="card side-card"><h2 class="section-title">Manager</h2><div class="person"><div class="person-avatar">{{initial(task.managerName)}}</div><div><strong>{{task.managerName||'Not assigned'}}</strong><span>Manager</span></div></div></div></aside></section></div>
</template>
<script setup>
import {ref,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import api from '../services/api';const route=useRoute(),router=useRouter(),task=ref({}),message=ref('');const pretty=s=>s?.replaceAll('_',' ').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase())||'';const formatDate=d=>d?new Date(d).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';const initial=n=>(n||'?').charAt(0).toUpperCase();async function load(){try{task.value=(await api.get('/tasks/'+route.params.id)).data}catch(e){console.error(e)}}async function completeTask(){try{const t=task.value;await api.put('/tasks/'+t.id,{title:t.title,priority:t.priority,progress:100,status:'COMPLETED',description:t.description,startDate:t.startDate,endDate:t.endDate,employeeId:t.employeeId,managerId:t.managerId});task.value={...t,progress:100,status:'COMPLETED'};message.value='Task marked as completed.'}catch(e){message.value='Could not update the task.'}}onMounted(load)
</script>
